// Function to calculate M
double M(double z, double h) {
    return (z*z*z*z * alpha*alpha) / (16*mu) * (3*pow(1+h/alpha, 4) - 4*pow(1+h/alpha, 2) + 1 - 4*pow(1+h/alpha, 4) * log(1+h/alpha));
}

// Function to calculate p
double p(double z, double h) {
    return -gamma * ((pow(h', 2)) / (1 + pow(h', 2))^(3/2)) - gamma * ((1 - alpha*h') / ((alpha+z) * (1 + pow(h', 2))^(1/2)));
}

// Function to calculate h'
double hPrime(double z) {
    return 162e-6 - 50e-6 * tanh(z-30);
}

