    int NZ = 100; // number of grid points in z-direction
    int NT = 100; // number of time steps
    double zEnd = 0.1; // [m]
    double dz = zEnd / (NZ-1); // [m]
    double dt = tEnd / (NT-1); // [s]

    // Initialize arrays for h and p
    std::vector<double> h(NZ, 0);
    std::vector<double> pH(NZ, 0);
    h[0] = h0;
    pH[0] = p0;

    // Initialize boundary conditions
    h[0] = h0;
    h[NZ-1] = h0;

    for (int n=0; n<NT; n++) {
        for (int i=1; i<NZ-1; i++) {
            double z = i*dz;
            double hCurrent = h[i];
            double hPrimeCurrent = hPrime(z);
            double MCurrent = M(z, hCurrent);
            double denominator = 1/(alpha + hCurrent);
            double pCurrent = p(z, hCurrent);
            p[0] = pH[0];

            // Update h and p
            h[i] = hCurrent - dt * denominator * (MCurrent * (pCurrent - pH[i-1]) / dz);
            pH[i] = pH[i-1] + dt * (pCurrent - pH[i-1]);
        }
    }

    // Print results
    for (int i=0; i<NZ; i++) {
        std::cout << h[i] << " " << pH[i] << std::endl;
    }

    return 0;
}
