        elif predicted_index in labels['outside']:
            return 'Outside the house: ' + KhoiDinh.get_outside_room_name(predicted_index)
        else:
            return 'Cannot identify the room.'

    def run(self):
        while True:
            text = input("Enter the text you want to identify the room: ")
