// Максимальное количество потоков
const int MAX_THREADS = 10;

// Функция для вычисления интеграла методом прямоугольников
double integrateRectangles(double a, double b, int n, double (*func)(double)) {
    double h = (b - a) / n;
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += func(a + i * h) * h;
    }
    return sum;
}

// Функция для вычисления интеграла методом трапеций
double integrateTrapezoids(double a, double b, int n, double (*func)(double)) {
    double h = (b - a) / n;
    double sum = 0.5 * (func(a) + func(b));
    for (int i = 1; i < n; i++) {
        sum += func(a + i * h);
    }
    return sum * h;
}

// Функция для вычисления интеграла методом Симпсона
double integrateSimpson(double a, double b, int n, double (*func)(double)) {
    double h = (b - a) / n;
    double sum = func(a) + func(b);
    for (int i = 1; i < n; i++) {
        sum += 2 * func(a + i * h);
    }
    return sum * h / 3.0;
}

// Функция для вычисления заданной функции
double func(double x) {
    //Ваш этап здесь
    return x * x;
}

// Функция для вычисления интеграла в потоке
DWORD WINAPI threadFunc(LPVOID lpParam) {
    int threadId = (int)(long)lpParam;
    double a = 0.0, b = 1.0, n = 1000;
    double (*func)(double) = func;
    double integral = 0.0;

    // Создать мьютекс для синхронизации вывода
    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);
    if (mutex == NULL) {
        return 0;
    }

    // Вычислить интеграл методом прямоугольников
    integral = integrateRectangles(a, b, n, func);

    // Удержать мьютекс на 1 секунду для имитации задержки
    Sleep(1000);

    // Вывести результат в переменную
    ReleaseMutex(mutex);
    printf("Thread %d: Rectangles integral = %f\n", threadId, integral);

    // Вычислить интеграл методом трапеций
    integral = integrateTrapezoids(a, b, n, func);

    // Удержать мьютекс на 1 секунду для имитации задержки
    Sleep(1000);

    // Вывести результат в переменную
    LockMutex(mutex);
    printf("Thread %d: Trapezoids integral = %f\n", threadId, integral);
    ReleaseMutex(mutex);

    // Вычислить интеграл методом Симпсона
    integral = integrateSimpson(a, b, n, func);

    // Удержать мьютекс на 1 секунду для имитации задержки
    Sleep(1000);

    // Вывести результат в переменную
    LockMutex(mutex);
    printf("Thread %d: Simpson integral = %f\n", threadId, integral);
    ReleaseMutex(mutex);

    // Уничтожить мьютекс
    CloseHandle(mutex);

    return 0;
}

int main() {
    // Создать вектор для хранения идентификаторов потоков
    std::vector HANDLE threads;

    // Создать SEMAPHORE для ожидания завершения вычислений
    HANDLE semaphore = CreateSemaphore(NULL, 0, MAX_THREADS, NULL);
    if (semaphore == NULL) {
        return 1;
    }

    // Создать мьютекс для синхронизации вывода
    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);
    if (mutex == NULL) {
        return 1;
    }

    // Создать и запустить потоки
    for (int i = 0; i < MAX_THREADS; i++) {
        HANDLE thread = CreateThread(NULL, 0, threadFunc, (LPVOID)i, 0, NULL);
        threads.push_back(thread);
    }

    // Ожидать завершения вычислений всех потоков
    for (int i = 0; i < MAX_THREADS; i++) {
        ReleaseSemaphore(semaphore, 1, NULL);
        WaitForSingleObject(semaphore, INFINITE);
    }

    // Уничтожить семафор
    CloseHandle(semaphore);

    // Уничтожить мьютекс
    CloseHandle(mutex);

    // Уничтожить потоки
    for (auto &thread : threads) {
        CloseHandle(thread);
    }

    return 0;
}
