    this.clientX = clientId;
    this.clientSec = clientSecret;
    this.authToken = null;
    this.isLoggedIn = false;
  }

  async login() {
    try {
      const response = await fetch(`https://accounts.google.com/o/oauth2/v2/auth?client_id=${this.clientX}&response_type=code&redirect_uri=http://localhost:3000/ callback&scope=openid profile email`);
      const code = await response.json();
      const accessToken = await fetch(`https://oauth2.googleapis.com/token?grant_type=authorization_code&code=${code}&redirect_uri=http://localhost:3000/callback&client_id=${this.clientX}&client_secret=${this.clientSec}`)
          .then(response => response.json());
      this.authToken = accessToken.access_token;
      this.isLoggedIn = true;
    } catch (error) {
      console.error(error);
    }
  }

  async logout() {
    this.authToken = null;
    this.isLoggedIn = false;
  }

  checkAuthenticated() {
    return this.isLoggedIn && this.authToken !== null;
  }
}

