        return this.board[0][2];
    }
    return null;
};

TicTacToe.prototype.playComputer = function() {
    let aiMove = this.minimax(this.player2, true);
    this.playerMove(this.player2, aiMove + 1);
};

TicTacToe.prototype.minimax = function(player, isMaximizing) {
    let bestMove = 0;
    let bestScore = -Infinity;
    for (let i = 0; i < this.board.length * this.board.length; i++) {
        if (this.board[Math.floor(i / this.board.length)][i % this.board.length] === 0) {
