            let score = this.checkWin();
            if (score === this.player1) {
                score = -100;
            } else if (score === this.player2) {
                score = 100;
            } else {
                score = this.minimax(this.player1, false);
            }
            this.playerMove(0, i + 1);
            if (isMaximizing) {
